/* =====================================================================
   APLICATIVO - SCRIPT A02: INSERCION DE DATOS AMPLIADOS
   Base: mining_casava (MySQL 8.0.46) - ejecutar DESPUES de A01.

   TODOS LOS DATOS SON FICTICIOS (RUC, DNI, placas, razones sociales,
   nombres, licencias y claves de usuario).

   Contenido:
     - Seccion 0: 3 tablas nuevas del aplicativo (usuarios, auditoria de
       accesos y auditoria de cambios). A01 no las incluye; se crean aqui.
     - 26 empresas, 4 transportistas, 16 vehiculos, 18 conductores, 10 productos
     - 602 guias de remision repartidas en 4 meses (julio a octubre de 2026),
       con ritmo de 30 a 40 guias por semana, mas sus tablas hijas:
       detalle, bienes, traslados y documentos relacionados.
     - 7 usuarios de prueba (2 externos, 2 empleados, 2 gestores, 1 administrador).

   Cargar ANTES de crear los triggers (A04): asi la carga inicial no llena
   la tabla de auditoria de cambios.

   Para repetir la carga: ejecutar A01 de nuevo (hace DROP DATABASE) y luego A02.
   Ejecutar seccion por seccion para sacar capturas.
   ===================================================================== */

USE mining_casava;

/* ---------- SECCION 0. TABLAS DE SEGURIDAD Y AUDITORIA ---------- */

-- 0.1 Usuarios del aplicativo (la clave nunca se guarda en texto plano:
--     Clave_hash = SHA2(CONCAT(Salt, clave), 256))
CREATE TABLE USUARIO_APP (
    Id_usuario         INT          NOT NULL AUTO_INCREMENT,
    Usuario            VARCHAR(30)  NOT NULL,
    Nombre_completo    VARCHAR(100) NOT NULL,
    Salt               CHAR(16)     NOT NULL,
    Clave_hash         CHAR(64)     NOT NULL,
    Rol                VARCHAR(15)  NOT NULL,
    Estado             VARCHAR(10)  NOT NULL DEFAULT 'ACTIVO',
    Intentos_fallidos  TINYINT      NOT NULL DEFAULT 0,
    Ultimo_acceso      DATETIME     NULL,
    Fecha_creacion     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    Fecha_cambio_clave DATETIME     NULL,
    CONSTRAINT pk_usuario_app PRIMARY KEY (Id_usuario),
    CONSTRAINT uq_usuario_app UNIQUE (Usuario),
    CONSTRAINT ck_usuario_rol    CHECK (Rol IN ('EXTERNO','EMPLEADO','GESTOR','ADMINISTRADOR')),
    CONSTRAINT ck_usuario_estado CHECK (Estado IN ('ACTIVO','INACTIVO','BLOQUEADO'))
) ENGINE=InnoDB;

-- 0.2 Auditoria de ingresos (quien intento entrar, cuando, desde que equipo, con que resultado)
CREATE TABLE AUDITORIA_ACCESO (
    Id_acceso        BIGINT       NOT NULL AUTO_INCREMENT,
    Usuario_intentado VARCHAR(30) NOT NULL,
    Id_usuario       INT          NULL,
    Fecha_hora       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    Resultado        VARCHAR(10)  NOT NULL,
    Equipo           VARCHAR(100) NULL,
    Detalle          VARCHAR(150) NULL,
    CONSTRAINT pk_auditoria_acceso PRIMARY KEY (Id_acceso),
    CONSTRAINT ck_acceso_resultado CHECK (Resultado IN ('EXITO','FALLO','BLOQUEADO','CIERRE'))
) ENGINE=InnoDB;
CREATE INDEX idx_acceso_fecha   ON AUDITORIA_ACCESO (Fecha_hora);
CREATE INDEX idx_acceso_usuario ON AUDITORIA_ACCESO (Usuario_intentado);

-- 0.3 Trazabilidad de datos (la llenan los triggers de A04)
CREATE TABLE AUDITORIA_CAMBIOS (
    Id_cambio       BIGINT      NOT NULL AUTO_INCREMENT,
    Tabla_afectada  VARCHAR(30) NOT NULL,
    Operacion       VARCHAR(6)  NOT NULL,
    Clave_registro  VARCHAR(100) NOT NULL,
    Valores_antes   JSON        NULL,
    Valores_despues JSON        NULL,
    Usuario_app     VARCHAR(30) NOT NULL,
    Usuario_mysql   VARCHAR(100) NOT NULL,
    Fecha_hora      DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_auditoria_cambios PRIMARY KEY (Id_cambio),
    CONSTRAINT ck_cambios_operacion CHECK (Operacion IN ('INSERT','UPDATE','DELETE'))
) ENGINE=InnoDB;
CREATE INDEX idx_cambios_fecha ON AUDITORIA_CAMBIOS (Fecha_hora);
CREATE INDEX idx_cambios_tabla ON AUDITORIA_CAMBIOS (Tabla_afectada, Operacion);

SHOW TABLES;

