/* ---------- SECCION 7. USUARIOS DE PRUEBA DEL APLICATIVO ----------
   Claves (solo para pruebas): externo1/externo2 = Ext#2026, empleado1/2 = Emp#2026,
   gestor1/2 = Ges#2026, admin = Adm#2026 */


/* ---------- SECCION 8. VERIFICACION DE LA CARGA (capturas) ---------- */

-- 8.1 Filas por tabla
SELECT 'EMPRESA' AS tabla, COUNT(*) AS filas FROM EMPRESA
UNION ALL SELECT 'TRANSPORTISTA', COUNT(*) FROM TRANSPORTISTA
UNION ALL SELECT 'VEHICULO', COUNT(*) FROM VEHICULO
UNION ALL SELECT 'CONDUCTOR', COUNT(*) FROM CONDUCTOR
UNION ALL SELECT 'PRODUCTO', COUNT(*) FROM PRODUCTO
UNION ALL SELECT 'GUIA_DE_REMISION', COUNT(*) FROM GUIA_DE_REMISION
UNION ALL SELECT 'DETALLE_GUIA', COUNT(*) FROM DETALLE_GUIA
UNION ALL SELECT 'BIEN_TRANSPORTADO', COUNT(*) FROM BIEN_TRANSPORTADO
UNION ALL SELECT 'TRASLADO', COUNT(*) FROM TRASLADO
UNION ALL SELECT 'DOCUMENTO_RELACIONADO', COUNT(*) FROM DOCUMENTO_RELACIONADO
UNION ALL SELECT 'USUARIO_APP', COUNT(*) FROM USUARIO_APP;

-- 8.2 Guias por mes y por tipo
SELECT DATE_FORMAT(Fecha, '%Y-%m') AS mes, COUNT(*) AS guias,
       SUM(Tipo_guia = 'Remitente') AS remitente, SUM(Tipo_guia = 'Transportista') AS transportista
FROM GUIA_DE_REMISION GROUP BY DATE_FORMAT(Fecha, '%Y-%m') ORDER BY mes;

-- 8.3 Guias por semana (la empresa emite entre 30 y 40)
SELECT YEARWEEK(Fecha, 1) AS semana, MIN(Fecha) AS desde, MAX(Fecha) AS hasta, COUNT(*) AS guias
FROM GUIA_DE_REMISION GROUP BY YEARWEEK(Fecha, 1) ORDER BY semana;

-- 8.4 Variedad de casos
SELECT Tipo_guia, Modalidad_traslado, Motivo_traslado, COUNT(*) AS guias
FROM GUIA_DE_REMISION GROUP BY Tipo_guia, Modalidad_traslado, Motivo_traslado
ORDER BY Tipo_guia, guias DESC;

-- 8.5 Razones por guia
SELECT g.total AS guias,
       ROUND((SELECT COUNT(*) FROM BIEN_TRANSPORTADO)     / g.total, 2) AS items_por_guia,
       ROUND((SELECT COUNT(*) FROM TRASLADO)              / g.total, 2) AS traslado_por_guia,
       ROUND((SELECT COUNT(*) FROM DOCUMENTO_RELACIONADO) / g.total, 2) AS documentos_por_guia
FROM (SELECT COUNT(*) AS total FROM GUIA_DE_REMISION) g;

-- 8.6 Usuarios (la clave aparece como hash, nunca en claro)
SELECT Id_usuario, Usuario, Rol, Estado, LEFT(Clave_hash, 16) AS hash_inicio FROM USUARIO_APP;


/* ---------- SECCION 9. PRUEBAS DE RESTRICCIONES (DEBEN FALLAR) ----------
   Ejecutar UNA POR UNA. Cada una tiene que dar error. */

-- 9.1 Peso en cero -> ck_guia_peso
  Punto_partida, Punto_llegada, Peso_bruto_total_carga, Unidad_medida_peso_bruto, Modalidad_traslado, RUC_Remitente, RUC_Destinatario)
SELECT 'EG07-99999991', 'Remitente', CURDATE(), '08:00:00', 'Venta', CURDATE(), 'A', 'B', 0, 'TNE', 'Privado', RUC, RUC FROM EMPRESA LIMIT 1;

-- 9.2 Guia Remitente sin modalidad -> ck_guia_modalidad_oblig
  Punto_partida, Punto_llegada, Peso_bruto_total_carga, Unidad_medida_peso_bruto, Modalidad_traslado, RUC_Remitente, RUC_Destinatario)
SELECT 'EG07-99999992', 'Remitente', CURDATE(), '08:00:00', 'Venta', CURDATE(), 'A', 'B', 10, 'TNE', NULL, RUC, RUC FROM EMPRESA LIMIT 1;

-- 9.3 Motivo Compra sin proveedor -> ck_guia_compra
  Punto_partida, Punto_llegada, Peso_bruto_total_carga, Unidad_medida_peso_bruto, Modalidad_traslado, RUC_Remitente, RUC_Destinatario)
SELECT 'EG07-99999993', 'Remitente', CURDATE(), '08:00:00', 'Compra', CURDATE(), 'A', 'B', 10, 'TNE', 'Privado', RUC, RUC FROM EMPRESA LIMIT 1;

-- 9.4 Modalidad Publico sin transportista -> ck_guia_publico
  Punto_partida, Punto_llegada, Peso_bruto_total_carga, Unidad_medida_peso_bruto, Modalidad_traslado, RUC_Remitente, RUC_Destinatario)
SELECT 'EG07-99999994', 'Remitente', CURDATE(), '08:00:00', 'Venta', CURDATE(), 'A', 'B', 10, 'TNE', 'Publico', RUC, RUC FROM EMPRESA LIMIT 1;

-- 9.5 RUC inexistente (clave foranea) -> fk_guia_remitente
  Punto_partida, Punto_llegada, Peso_bruto_total_carga, Unidad_medida_peso_bruto, Modalidad_traslado, RUC_Remitente, RUC_Destinatario)
SELECT 'EG07-99999995', 'Remitente', CURDATE(), '08:00:00', 'Venta', CURDATE(), 'A', 'B', 10, 'TNE', 'Privado', '20000000000', RUC FROM EMPRESA LIMIT 1;

-- 9.6 Licencia repetida (UNIQUE) -> uq_conductor_licencia
SELECT '99999999', 'PRUEBA REPETIDA', Nro_Licencia FROM CONDUCTOR LIMIT 1;

-- 9.7 Borrar una empresa con guias -> falla por clave foranea
DELETE FROM EMPRESA WHERE RUC = (SELECT RUC_Remitente FROM GUIA_DE_REMISION LIMIT 1);

-- 9.8 Rol invalido en USUARIO_APP -> ck_usuario_rol
VALUES ('prueba_mala', 'PRUEBA', '0000000000000000', SHA2('x', 256), 'SUPERUSUARIO');

